const c = items?.[0]?.json ?? {};

const cfg = {
  baseUrl: c.baseUrl || 'https://www.melnick.com.br/empreendimentos/',
  maxClicksVerMais: Number(c.maxClicksVerMais ?? 10),
  maxEmpreendimentos: Number(c.maxEmpreendimentos ?? 60),
  navTimeoutMs: Number(c.navTimeoutMs ?? 90000),
  waitAfterClickMs: Number(c.waitAfterClickMs ?? 1200)
};

const script = `
const { chromium } = require('playwright');

const cfg = ${JSON.stringify(cfg)};

function uniq(arr) {
  return [...new Set((arr || []).filter(Boolean))];
}

function normalizeUrl(url) {
  try {
    return String(url)
      .trim()
      .replace(/[#?].*$/, '')
      .replace(/\/$/, '') + '/';
  } catch (e) {
    return null;
  }
}

function classify(urls) {
  const plantas = [];
  const galeria = [];
  const caracteristicas = [];
  const outras = [];

  for (const u of urls) {
    const s = String(u).toLowerCase();
    if (/planta|floor|tipologia|implantacao|implanta/.test(s)) {
      plantas.push(u);
    } else if (/icone|icon|caracteristica|feature|amenit/.test(s)) {
      caracteristicas.push(u);
    } else if (/galeria|gallery|fachada|decorado|interna|externa|lazer|piscina|rooftop|living|suite|dormitorio/.test(s)) {
      galeria.push(u);
    } else {
      outras.push(u);
    }
  }

  return {
    plantas: uniq(plantas),
    galeria: uniq(galeria),
    caracteristicas: uniq(caracteristicas),
    outras: uniq(outras)
  };
}

function extractImagesFromHtml(html) {
  const regex = /https?:\\/\\/[^\\s"'<>]+\\.(?:jpg|jpeg|png|webp|gif)(?:\\?[^"'<>\\s]+)?/gi;
  const out = [];
  while (true) {
    const m = regex.exec(html);
    if (!m) break;
    const u = String(m[0]).replace(/&amp;/g, '&');
    if (!u.startsWith('data:image')) out.push(u);
  }
  return uniq(out);
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  const result = {
    status: 'ok',
    origem: 'playwright',
    baseUrl: cfg.baseUrl,
    totalLinks: 0,
    links: [],
    items: [],
    erros: []
  };

  try {
    await page.goto(cfg.baseUrl, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs });

    for (let i = 0; i < cfg.maxClicksVerMais; i++) {
      const btn = page.locator('button:has-text("Ver mais"), a:has-text("Ver mais"), text=/ver mais/i').first();
      const count = await btn.count();
      if (!count) break;
      try {
        await btn.click({ timeout: 4000 });
        await page.waitForTimeout(cfg.waitAfterClickMs);
      } catch (e) {
        break;
      }
    }

    const hrefs = await page.$$eval('a[href]', (els) => els.map((a) => a.href));
    const links = uniq(hrefs
      .map((h) => normalizeUrl(h))
      .filter((h) => h && /\\/enterprise\\//i.test(h))
    ).slice(0, cfg.maxEmpreendimentos);

    result.links = links;
    result.totalLinks = links.length;

    for (const empreendimentoUrl of links) {
      const p = await context.newPage();
      try {
        await p.goto(empreendimentoUrl, { waitUntil: 'domcontentloaded', timeout: cfg.navTimeoutMs });
        await p.waitForTimeout(800);

        const pageData = await p.evaluate(() => {
          const nome = (document.querySelector('h1')?.textContent || '').trim() || null;

          const raw = [];

          for (const img of Array.from(document.querySelectorAll('img'))) {
            if (img.src) raw.push(img.src);
            const ss = img.getAttribute('srcset');
            if (ss) raw.push(...ss.split(',').map((x) => x.trim().split(' ')[0]).filter(Boolean));
          }

          for (const source of Array.from(document.querySelectorAll('source'))) {
            const ss = source.getAttribute('srcset');
            if (ss) raw.push(...ss.split(',').map((x) => x.trim().split(' ')[0]).filter(Boolean));
          }

          for (const a of Array.from(document.querySelectorAll('a[href]'))) {
            const href = a.getAttribute('href');
            if (href) raw.push(href);
          }

          return { nome, raw };
        });

        const html = await p.content();
        const fromHtml = extractImagesFromHtml(html);

        const rawImageUrls = uniq([
          ...pageData.raw,
          ...fromHtml
+        ]).filter((u) => /^https?:\\/\\//i.test(u) && /\\.(jpg|jpeg|png|webp|gif)(\\?|$)/i.test(u));
+
+        const buckets = classify(rawImageUrls);
+
+        result.items.push({
+          nome: pageData.nome,
+          url: empreendimentoUrl,
+          rawImageUrls,
+          galeria: buckets.galeria,
+          plantas: buckets.plantas,
+          caracteristicas: buckets.caracteristicas,
+          outras: buckets.outras,
+          origemClassificacao: 'heuristica_playwright'
+        });
+      } catch (e) {
+        result.erros.push({
+          url: empreendimentoUrl,
+          erro: String(e && e.message ? e.message : e)
+        });
+      } finally {
+        await p.close().catch(() => {});
+      }
+    }
+  } catch (e) {
+    result.status = 'erro';
+    result.erros.push({ etapa: 'coleta_links', erro: String(e && e.message ? e.message : e) });
+  } finally {
+    await browser.close().catch(() => {});
+  }
+
+  console.log(JSON.stringify(result));
+})().catch((e) => {
+  console.error(String(e && e.stack ? e.stack : e));
+  process.exit(1);
+});
+`;
+
+const escaped = script
+  .replace(/\\/g, '\\\\')
+  .replace(/"/g, '\\"')
+  .replace(/\n/g, ' ');
+
+const command = `npx -y -p playwright node -e "${escaped}"`;
+
+return [{
+  json: {
+    ...c,
+    command
+  }
+}];

const raw = items?.[0]?.json ?? {};
const stdout = String(raw.stdout ?? '').trim();
const stderr = String(raw.stderr ?? '').trim();

let payload = null;

try {
  payload = JSON.parse(stdout);
} catch (e) {
  const lines = stdout.split(/\r?\n/).map((x) => x.trim()).filter(Boolean);
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      payload = JSON.parse(lines[i]);
      break;
    } catch (e2) {
      // tenta linha anterior
    }
  }
}

if (!payload || typeof payload !== 'object') {
  return [{
    json: {
      status: 'erro_parse_stdout',
      stdout,
      stderr,
      hint: 'Nao foi possivel interpretar JSON do Execute Command.'
    }
  }];
}

const itemsOut = Array.isArray(payload.items) ? payload.items : [];
if (!itemsOut.length) {
  return [{
    json: {
      ...payload,
      stderr
    }
  }];
}

return itemsOut.map((x, i) => ({
  json: {
    indice: i + 1,
    total: itemsOut.length,
    ...x,
    _meta: {
      status: payload.status,
      origem: payload.origem,
      totalLinks: payload.totalLinks,
      links: payload.links,
      erros: payload.erros,
      stderr
    }
  }
}));
